def get_repo_metadata(fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0184000" if __import__("os").path.isdir("./environment_mix/0184000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate fields
    if fields is not None:
        if not isinstance(fields, list) or any(not isinstance(x, str) for x in fields):
            return _err("VALIDATION_ERROR", "`fields` must be an array of strings.")
        if len(fields) == 0:
            return _err("VALIDATION_ERROR", "`fields` must include at least one field.")

    data = _load("repo_metadata.json")
    # Stored as list of rows; return first snapshot object if present
    meta = None
    if isinstance(data, list):
        meta = data[0] if data else None
    elif isinstance(data, dict):
        meta = data
    else:
        meta = None

    if not isinstance(meta, dict) or not meta:
        return _err("NOT_FOUND", "Repository metadata is not available in the snapshot.")

    if fields is None:
        return {"data": meta}

    out = {k: meta[k] for k in fields if k in meta}
    if not out:
        return _err("VALIDATION_ERROR", "No requested fields exist in the metadata snapshot.")
    return {"data": out}

def list_issues_prs(state=None, user=None, number=None, limit=None, fields=None, **_extra):
