def list_commits(author=None, since=None, until=None, sha=None, limit=None, fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0184000" if __import__("os").path.isdir("./environment_mix/0184000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_iso_z(s):
        # Accept 'Z' suffix and offsets supported by fromisoformat
        if not isinstance(s, str) or not s:
            raise ValueError("invalid")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    # Validate inputs
    if author is not None and not isinstance(author, str):
        return _err("VALIDATION_ERROR", "`author` must be a string.")
    if sha is not None and not isinstance(sha, str):
        return _err("VALIDATION_ERROR", "`sha` must be a string.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "`limit` must be an integer.")
    if limit <= 0:
        return _err("VALIDATION_ERROR", "`limit` must be a positive integer.")
    if fields is not None:
        if not isinstance(fields, list) or any(not isinstance(x, str) for x in fields):
            return _err("VALIDATION_ERROR", "`fields` must be an array of strings.")

    since_dt = None
    until_dt = None
    if since is not None:
        try:
            since_dt = _parse_iso_z(since)
        except ValueError:
            return _err("VALIDATION_ERROR", "`since` must be a valid ISO date-time string.")
    if until is not None:
        try:
            until_dt = _parse_iso_z(until)
        except ValueError:
            return _err("VALIDATION_ERROR", "`until` must be a valid ISO date-time string.")
    if since_dt is not None and until_dt is not None and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "`since` must be earlier than or equal to `until`.")

    rows = _load("commits.json")
    if not isinstance(rows, list):
        rows = []

    def _commit_dt(it):
        d = it.get("date")
        if not isinstance(d, str):
            return None
        try:
            return _parse_iso_z(d)
        except ValueError:
            return None

    # Sort by date descending when possible (snapshot-like)
    sortable = []
    for it in rows:
        if isinstance(it, dict):
            sortable.append(((_commit_dt(it) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), it))
    sortable.sort(key=lambda x: x[0], reverse=True)
    rows_sorted = [it for _, it in sortable]

    # Filter
    filtered = []
    for it in rows_sorted:
        if sha is not None and it.get("sha") != sha:
            continue
        if author is not None and it.get("author") != author:
            continue
        dt = _commit_dt(it)
        if since_dt is not None and dt is not None and dt < since_dt:
            continue
        if until_dt is not None and dt is not None and dt > until_dt:
            continue
        filtered.append(it)

    # sha provided -> single or NOT_FOUND
    if sha is not None:
        if not filtered:
            return _err("NOT_FOUND", f"No commit with sha {sha} exists in the snapshot.")
        item = filtered[0]
        if fields is not None:
            item = {k: item.get(k) for k in fields}
        return {"data": item}

    total = len(filtered)
    page = filtered[:limit]
    if fields is not None:
        page = [{k: it.get(k) for k in fields} for it in page]

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": total > limit,
            "next_cursor": None
        }
    }

