def get_toolset(toolset_name=None, fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0184000" if __import__("os").path.isdir("./environment_mix/0184000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    allowed = {"toolset_name", "description", "tools", "allowed_shell_operators", "default_directory"}

    if toolset_name is not None and not isinstance(toolset_name, str):
        return _err("VALIDATION_ERROR", "`toolset_name` must be a string.")
    if fields is not None:
        if not isinstance(fields, list):
            return _err("VALIDATION_ERROR", "`fields` must be an array.")
        if any(not isinstance(x, str) for x in fields):
            return _err("VALIDATION_ERROR", "`fields` must be an array of strings.")
        if any(x not in allowed for x in fields):
            return _err("VALIDATION_ERROR", "Unknown field in `fields`.", allowed_fields=sorted(allowed))

    rows = _load("toolsets.json")
    if not isinstance(rows, list):
        rows = []

    if toolset_name is None:
        if not rows:
            return _err("NOT_FOUND", "No toolsets are available in the snapshot.")
        ts = rows[0]
    else:
        ts = None
        for it in rows:
            if isinstance(it, dict) and it.get("toolset_name") == toolset_name:
                ts = it
                break
        if ts is None:
            return _err("NOT_FOUND", f"No toolset with name '{toolset_name}' exists in the snapshot.")

    if fields is None:
        return {"data": ts}
    out = {k: ts.get(k) for k in fields if k in ts}
    return {"data": out}

