def get_readme(format=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0184000" if __import__("os").path.isdir("./environment_mix/0184000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if format is None:
        format = "raw"
    if not isinstance(format, str) or format not in ("raw", "text"):
        return _err("VALIDATION_ERROR", "`format` must be one of: raw, text.")

    # README is not a collection; check common snapshot locations in this datastore
    candidate_paths = [
        os.path.join(_DB, "README.md"),
        os.path.join(_DB, "readme.md"),
        os.path.join(_DB, "README.txt"),
        os.path.join(_DB, "README"),
    ]
    readme_path = None
    for p in candidate_paths:
        if os.path.isfile(p):
            readme_path = p
            break

    if readme_path is None:
        return _err("NOT_FOUND", "README content is not available in the snapshot.")

    try:
        with open(readme_path, "r", encoding="utf-8") as f:
            raw = f.read()
    except OSError:
        return _err("NOT_FOUND", "README content is not available in the snapshot.")

    if format == "raw":
        return {"data": {"format": "raw", "content": raw}}

    # "text": best-effort plain text; for markdown just return as-is.
    return {"data": {"format": "text", "content": raw}}
